test "test_risk_result_codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const msg = RiskResult{
        .req_id = 123456789,
        .decision = 42,
        .code = 1234,
        .rule_id = 1234,
        .ts_recv_ns = 123456789,
        .ts_engine_ns = 123456789,
        .text = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
    };

    var buf = codec.Buffer.init(allocator, .big);
    defer buf.deinit();
    try msg.encode(&buf);

    var reader = codec.Reader.init(buf.written(), .big);
    const decoded = try RiskResult.decode(allocator, &reader);
    defer decoded.deinit(allocator);
    try std.testing.expect(msg.eql(decoded));
}
